const { products } = require('../catalog');

const tokens = (s) => s.toLowerCase().split(/[^a-z0-9]+/).filter(Boolean);
const index = new Map();
for (const p of products) {
  for (const t of tokens(p.name)) {
    if (!index.has(t)) index.set(t, new Set());
    index.get(t).add(p.id);
  }
}

function search(q) {
  const needle = q.trim().toLowerCase();
  const exact = products.filter((p) => p.sku.toLowerCase() === needle);
  const ids = new Set();
  for (const t of tokens(q)) for (const id of index.get(t) ?? []) ids.add(id);
  return [...exact, ...products.filter((p) => ids.has(p.id) && !exact.includes(p))];
}

module.exports = { search };
