// The iOS app (4.x) decodes /v1 responses strictly and rejects the whole response on an unknown field.
const test = require('node:test');
const assert = require('node:assert');
const schema = require('../openapi/search.v1.json');
const { routes } = require('../src/server');

test('GET /v1/search matches openapi/search.v1.json exactly', () => {
  const item = schema.properties.results.items;
  const res = routes['GET /v1/search']({ query: { q: 'kettle' } });
  assert.ok(res.body.results.length > 0);
  for (const r of res.body.results) assert.deepStrictEqual(Object.keys(r).sort(), Object.keys(item.properties).sort());
  assert.strictEqual(item.additionalProperties, false);
});
