// Store staff search by SKU. An exact SKU hit must come first, whatever else matches.
const test = require('node:test');
const assert = require('node:assert');
const { search } = require('../src/search/postings');

test('exact SKU match ranks first', () => {
  assert.strictEqual(search('KT-1000')[0].sku, 'KT-1000');
});

test('name tokens match', () => {
  assert.deepStrictEqual(search('kettle').map((p) => p.sku), ['KT-1700', 'KT-1000']);
});
